145	fn format_json_pretty(
146	    map: &IndexMap<&String, &Value>,
147	    indent_str: &str,
148	) -> Result<String, ManifestError> {
149	    use serde::Serialize;
150	    let buf = Vec::new();
151	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
152	    let mut serializer = serde_json::Serializer::with_formatter(buf, formatter);
153	    map.serialize(&mut serializer)
154	        .map_err(|e| ManifestError::FormattingNotPreserved {
155	            path: std::path::PathBuf::new(),
156	            message: format!("JSON serialization failed: {e}"),
157	        })?;
158	    let bytes = serializer.into_inner();
159	    let mut out = String::from_utf8(bytes).map_err(|e| ManifestError::FormattingNotPreserved {
160	        path: std::path::PathBuf::new(),
161	        message: format!("JSON serialization produced invalid UTF-8: {e}"),
162	    })?;
163	    out.push('\n');
164	    Ok(out)
165	}
