176	    fn is_publishable(&self) -> bool {
177	        if self.doc.get("name").is_none() {
178	            return false;
179	        }
180	        if let Some(b) = self.doc.get("private").and_then(|p| p.as_bool()) {
181	            if b {
182	                return false;
183	            }
184	        }
185	        true
186	    }
