188	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
189	        if !self.is_publishable() {
190	            return vec![callisto_model::PublishTarget::None];
191	        }
192	        // Read `publishConfig.registry` from package.json, the standard npm
193	        // mechanism for targeting a private registry. When set, `npm publish`
194	        // must receive `--registry <url>`; when absent, the public registry is
195	        // used (npm's built-in default).
196	        let publish_config = self.doc.get("publishConfig");
197	        let registry = publish_config
198	            .and_then(|pc| pc.get("registry"))
199	            .and_then(|r| r.as_str())
200	            .map(|s| s.to_string());
201	        // Read `publishConfig.access` to propagate the operator's explicit
202	        // access intent. npm's `--access` CLI flag overrides publishConfig.access,
203	        // so callisto must read it here and honour it in plan_publish rather than
204	        // blindly passing `--access public` for all scoped packages.
205	        let restricted = publish_config
206	            .and_then(|pc| pc.get("access"))
207	            .and_then(|a| a.as_str())
208	            == Some("restricted");
209	        vec![callisto_model::PublishTarget::Npm {
210	            registry,
211	            restricted,
212	        }]
213	    }
