283	    fn update_dependency_spec(
284	        &mut self,
285	        name: &str,
286	        kind: DepKind,
287	        new: DepSpec,
288	        permit: &ApplyPermit,
289	    ) -> Result<(), ManifestError> {
290	        if kind == DepKind::Build {
291	            return Err(ManifestError::DependencyNotFound {
292	                path: self.path.clone(),
293	                name: name.to_string(),
294	                kind,
295	            });
296	        }
297	
298	        let section_name = match kind {
299	            DepKind::Runtime => "dependencies",
300	            DepKind::Dev => "devDependencies",
301	            DepKind::Peer => "peerDependencies",
302	            DepKind::Optional => "optionalDependencies",
303	            DepKind::Build => unreachable!(),
304	        };
305	
306	        // Validate that the target dependency actually exists in the primary
307	        // section *before* mutating anything. This guarantees that a failed
308	        // update (dependency not found) leaves self.doc byte-for-byte
309	        // unchanged, including the overrides/resolutions tables below.
310	        let updated_in_section = self
311	            .doc
312	            .get(section_name)
313	            .and_then(|v| v.as_object())
314	            .is_some_and(|section| section.contains_key(name));
315	
316	        if !updated_in_section {
317	            return Err(ManifestError::DependencyNotFound {
318	                path: self.path.clone(),
319	                name: name.to_string(),
320	                kind,
321	            });
322	        }
323	
324	        if let Some(section) = self
325	            .doc
326	            .get_mut(section_name)
327	            .and_then(|v| v.as_object_mut())
328	        {
329	            section.insert(name.to_string(), Value::String(new.render()));
330	        }
331	
332	        for extra in ["overrides", "resolutions"] {
333	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut()) {
334	                if tbl.get(name).is_some_and(|v| v.is_string()) {
335	                    tbl.insert(name.to_string(), Value::String(new.render()));
336	                }
337	            }
338	        }
339	
340	        self.persist(permit)
341	    }
