395	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
396	    match spec {
397	        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
398	        DepSpec::Range(_, original) => {
399	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
400	            if rest.contains(' ')
401	                || rest.contains('-')
402	                || rest.contains('|')
403	                || rest.contains(['x', 'X', '*'])
404	            {
405	                return None;
406	            }
407	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
408	            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
409	            Some(DepSpec::Range(req, rendered))
410	        }
411	        _ => None,
412	    }
413	}
414	
415	fn render_at_precision(target: &Version, original_clause: &str) -> String {
416	    let parts: Vec<&str> = original_clause.split('.').collect();
417	    let maj = target.major().unwrap_or(0);
418	    let min = target.minor().unwrap_or(0);
419	    let pat = target.patch().unwrap_or(0);
420	
421	    match parts.len() {
422	        1 => format!("{maj}"),
423	        2 => format!("{maj}.{min}"),
424	        _ => format!("{maj}.{min}.{pat}"),
425	    }
426	}
