273	            provenance.insert(ConfigKey::CASCADE_BUMP_SEVERITY, ConfigProvenance::Explicit);
274	            CascadeBumpSeverity::Minor
275	        }
276	        Some("patch") | None => CascadeBumpSeverity::Patch,
277	        Some(other) => {
278	            return Err(ConfigError::InvalidBumpSeverity {
279	                found: other.to_string(),
280	            })
281	        }
282	    };
283	
284	    let peer_escalation = cascade_raw.peer_escalation.unwrap_or(true);
285	    if cascade_raw.peer_escalation.is_some() {
286	        provenance.insert(
287	            ConfigKey::CASCADE_PEER_ESCALATION,
288	            ConfigProvenance::Explicit,
289	        );
290	    }
291	
292	    let preserve_npm_ranges = cascade_raw.preserve_npm_ranges.unwrap_or(true);
293	    if cascade_raw.preserve_npm_ranges.is_some() {
294	        provenance.insert(
295	            ConfigKey::CASCADE_PRESERVE_NPM_RANGES,
296	            ConfigProvenance::Explicit,
297	        );
298	    }
299	
300	    let validation_raw = raw.validation.unwrap_or_default();
301	    let allow_empty_changesets = validation_raw.allow_empty_changesets.unwrap_or(false);
302	    if validation_raw.allow_empty_changesets.is_some() {
303	        provenance.insert(
304	            ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS,
305	            ConfigProvenance::Explicit,
306	        );
307	    }
308	
309	    let mut registries = BTreeMap::new();
310	    registries.insert(
311	        RegistryKey(RegistryKey::CRATES_IO.to_string()),
312	        RegistryConfig {
313	            kind: Ecosystem::Cargo,
314	            url: None,
315	        },
316	    );
317	    registries.insert(
318	        RegistryKey(RegistryKey::NPM.to_string()),
319	        RegistryConfig {
320	            kind: Ecosystem::Npm,
321	            url: None,
322	        },
323	    );
324	
325	    if let Some(raw_regs) = raw.registries {
326	        for (k_str, reg) in raw_regs {
327	            let key = RegistryKey(k_str);
328	            let kind = match reg.kind.as_deref() {
329	                Some("cargo") => Ecosystem::Cargo,
330	                Some("npm") | None => Ecosystem::Npm,
331	                Some("pypi") => Ecosystem::Pypi,
332	                Some(other) => {
333	                    return Err(ConfigError::UnknownKey {
334	                        path: callisto_toml.clone(),
335	                        key: format!("[registries] kind = {other:?}"),
336	                    })
337	                }
338	            };
339	            registries.insert(key, RegistryConfig { kind, url: reg.url });
340	        }
341	    }
342	
343	    let raw_groups = RawGroupTable {
344	        fixed: raw.fixed_group.unwrap_or_default(),
345	        linked: raw.linked_group.unwrap_or_default(),
346	    };
347	    GroupTable::validate_syntactic(&raw_groups)?;
348	
349	    // Resolve [[package]] blocks into per-package override rules.
350	    // Order is preserved: first matching rule wins during package construction.
351	    let mut packages: Vec<(PackageId, PackageConfig)> = Vec::new();
352	    for raw_pkg in raw.package.unwrap_or_default() {
353	        let pattern = PackageId::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
354	            path: callisto_toml.clone(),
355	            key: format!("[[package]] match = {:?}: {e}", raw_pkg.pattern),
356	        })?;
357	
358	        let release_trigger = raw_pkg
359	            .release_trigger
360	            .as_deref()
361	            .map(parse_release_trigger)
362	            .transpose()?;
363	
364	        let tag_template = raw_pkg
365	            .tag_template
366	            .as_deref()
367	            .map(TagTemplate::parse)
368	            .transpose()
369	            .map_err(ConfigError::Tag)?;
370	
371	        let changelog = raw_pkg
372	            .changelog
373	            .as_deref()
374	            .map(|s| {
375	                callisto_model::workspace_relative(s).map_err(|_err| {
376	                    ConfigError::InvalidChangelogPath {
377	                        pattern: raw_pkg.pattern.clone(),
378	                        value: s.to_string(),
379	                    }
380	                })
381	            })
382	            .transpose()?;
383	
384	        let pre_major_inference = raw_pkg
385	            .pre_major_inference
386	            .as_deref()
387	            .map(parse_pre_major_policy)
388	            .transpose()?;
389	
390	        let publish_to = raw_pkg
391	            .publish_to
392	            .as_deref()
393	            .map(|targets| {
394	                targets
395	                    .iter()
396	                    .map(|s| parse_publish_target(s))
397	                    .collect::<Result<Vec<_>, _>>()
398	            })
399	            .transpose()
400	            .map_err(|e| match e {
401	                ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
402	                    path: callisto_toml.clone(),
403	                    key: format!("[[package]] publish-to: {key}"),
404	                },
405	                other => other,
406	            })?;
407	
408	        packages.push((
409	            pattern,
410	            PackageConfig {
411	                release_trigger,
412	                publish_to,
413	                tag_template,
414	                changelog,
415	                pre_major_inference,
416	            },
417	        ));
418	    }
419	
420	    // Resolve [[package-set]] blocks into bulk config-override rules.
421	    // Semantics: each rule matches ALL packages whose PackageId matches the pattern.
422	    // A [[package]] rule takes priority; [[package-set]] is the fallback (see walk.rs).
423	    let mut package_sets: Vec<(PackagePattern, PackageConfig)> = Vec::new();
424	    for raw_pkg in raw.package_set.unwrap_or_default() {
425	        let pattern =
426	            PackagePattern::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
427	                path: callisto_toml.clone(),
428	                key: format!("[[package-set]] match = {:?}: {e}", raw_pkg.pattern),
429	            })?;
430	
431	        let release_trigger = raw_pkg
432	            .release_trigger
433	            .as_deref()
434	            .map(parse_release_trigger)
435	            .transpose()?;
436	
437	        let tag_template = raw_pkg
438	            .tag_template
439	            .as_deref()
440	            .map(TagTemplate::parse)
441	            .transpose()
442	            .map_err(ConfigError::Tag)?;
443	
444	        let changelog = raw_pkg
445	            .changelog
446	            .as_deref()
447	            .map(|s| {
448	                callisto_model::workspace_relative(s).map_err(|_err| {
449	                    ConfigError::InvalidChangelogPath {
450	                        pattern: raw_pkg.pattern.clone(),
451	                        value: s.to_string(),
452	                    }
453	                })
454	            })
455	            .transpose()?;
456	
457	        let pre_major_inference = raw_pkg
458	            .pre_major_inference
459	            .as_deref()
460	            .map(parse_pre_major_policy)
461	            .transpose()?;
462	
463	        let publish_to = raw_pkg
464	            .publish_to
465	            .as_deref()
466	            .map(|targets| {
467	                targets
468	                    .iter()
469	                    .map(|s| parse_publish_target(s))
470	                    .collect::<Result<Vec<_>, _>>()
471	            })
472	            .transpose()
473	            .map_err(|e| match e {
474	                ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
475	                    path: callisto_toml.clone(),
476	                    key: format!("[[package-set]] publish-to: {key}"),
477	                },
478	                other => other,
479	            })?;
480	
481	        package_sets.push((
482	            pattern,
483	            PackageConfig {
484	                release_trigger,
485	                publish_to,
486	                tag_template,
487	                changelog,
488	                pre_major_inference,
489	            },
490	        ));
491	    }
492	
493	    Ok(ResolvedConfig {
494	        root: root.to_path_buf(),
495	        changesets_dir,
496	        cascade: CascadeConfig {
497	            mode,
498	            bump_severity,
499	            peer_escalation,
500	            preserve_npm_ranges,
501	        },
502	        validation: ValidationConfig {
503	            allow_empty_changesets,
504	        },
505	        registries,
506	        packages,
507	        package_sets,
508	        groups: GroupTable::default(),
509	        raw_groups,
510	        provenance,
511	    })
512	}
