93	/// Validates git version against REQUIRED_GIT floor.
94	pub fn check_git_version(reported: &str) -> Result<(), CommandError> {
95	    let version_str = reported.trim();
96	    let digits = version_str
97	        .split_whitespace()
98	        .find(|word| word.chars().next().is_some_and(|c| c.is_ascii_digit()))
99	        .unwrap_or(version_str);
100	
101	    let parts: Vec<&str> = digits.split('.').collect();
102	    if parts.len() < 2 {
103	        return Err(CommandError::IncompatibleVersion {
104	            program: "git".to_string(),
105	            found: reported.to_string(),
106	            required: REQUIRED_GIT.to_string(),
107	        });
108	    }
109	
110	    let major: u64 = parts[0].parse().unwrap_or(0);
111	    let minor: u64 = parts[1].parse().unwrap_or(0);
112	
113	    if major < 2 || (major == 2 && minor < 20) {
114	        return Err(CommandError::IncompatibleVersion {
115	            program: "git".to_string(),
116	            found: reported.to_string(),
117	            required: REQUIRED_GIT.to_string(),
118	        });
119	    }
120	
121	    Ok(())
122	}
