33	/// Filters `all_tags` down to those matching `template`'s glob.
34	///
35	/// Uses the same `globset::Glob`-based matching
36	/// `callisto_vcs::GitRepository::list_tags` applies internally, kept in
37	/// sync deliberately so tag selection is byte-identical whether `all_tags`
38	/// was sourced via gix or the `CommandRunner` fallback in
39	/// [`fetch_all_tags`]. This includes error behavior: a `template.glob()`
40	/// that fails to compile is surfaced as `Err(GraphError::Vcs(VcsError::
41	/// InvalidGlob))`, matching every tag being the unsafe alternative -- a
42	/// malformed tag template must never silently make "last tag" resolution
43	/// pick an unrelated package's tag.
44	fn matching_tags<'a>(
45	    all_tags: &'a [String],
46	    template: &TagTemplate,
47	) -> Result<Vec<&'a str>, GraphError> {
48	    let glob = template.glob();
49	    let matcher = globset::Glob::new(&glob)
50	        .map(|g| g.compile_matcher())
51	        .map_err(|e| {
52	            GraphError::Vcs(callisto_vcs::VcsError::InvalidGlob {
53	                pattern: glob.clone(),
54	                message: e.to_string(),
55	            })
56	        })?;
57	
58	    Ok(all_tags
59	        .iter()
60	        .filter(|t| matcher.is_match(t.as_str()))
61	        .map(|s| s.as_str())
62	        .collect())
63	}
