67	fn select_from_tags(
68	    all_tags: &[String],
69	    template: &TagTemplate,
70	    grammar: VersionGrammar,
71	) -> Result<LastTagSelection, GraphError> {
72	    let candidates = matching_tags(all_tags, template)?;
73	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
74	}
