<title>Callisto Workspace Audit</title>
<style>
  :root {
    --bg: #f4f5f3;
    --surface: #ffffff;
    --surface-2: #ebecea;
    --border: #d8dad5;
    --text: #1b1e1c;
    --text-muted: #5a5f5a;
    --text-faint: #8a8f89;
    --accent: #1f7a72;
    --accent-soft: #e4f1ef;
    --link: #16645d;
    --crit-fg: #a3121a;
    --crit-bg: #fbe4e4;
    --crit-border: #e8a6a6;
    --high-fg: #9a5300;
    --high-bg: #fdecd2;
    --high-border: #edc182;
    --med-fg: #7a6400;
    --med-bg: #f8f0cf;
    --med-border: #ddca7e;
    --low-fg: #1f5a8a;
    --low-bg: #e2edf7;
    --low-border: #a9c8e0;
    --shadow: 0 1px 2px rgba(20,20,15,0.04), 0 4px 14px rgba(20,20,15,0.05);
    --serif: ui-serif, Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --mono: ui-monospace, "SF Mono", "Cascadia Code", "Roboto Mono", Menlo, Consolas, monospace;
  }

  :root[data-theme="dark"] {
    --bg: #14161a;
    --surface: #1b1e23;
    --surface-2: #22262c;
    --border: #30353c;
    --text: #e7e8e6;
    --text-muted: #a2a7ac;
    --text-faint: #6d7278;
    --accent: #5fc4ba;
    --accent-soft: #1c3532;
    --link: #7ad4ca;
    --crit-fg: #ff8f8f;
    --crit-bg: #3a1c1e;
    --crit-border: #6b2c2e;
    --high-fg: #ffbf6b;
    --high-bg: #3a2b14;
    --high-border: #6b4a1e;
    --med-fg: #eddb7a;
    --med-bg: #35300f;
    --med-border: #62551d;
    --low-fg: #8fc3ee;
    --low-bg: #17293a;
    --low-border: #2b4b68;
    --shadow: 0 1px 2px rgba(0,0,0,0.3), 0 6px 20px rgba(0,0,0,0.35);
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #14161a;
      --surface: #1b1e23;
      --surface-2: #22262c;
      --border: #30353c;
      --text: #e7e8e6;
      --text-muted: #a2a7ac;
      --text-faint: #6d7278;
      --accent: #5fc4ba;
      --accent-soft: #1c3532;
      --link: #7ad4ca;
      --crit-fg: #ff8f8f;
      --crit-bg: #3a1c1e;
      --crit-border: #6b2c2e;
      --high-fg: #ffbf6b;
      --high-bg: #3a2b14;
      --high-border: #6b4a1e;
      --med-fg: #eddb7a;
      --med-bg: #35300f;
      --med-border: #62551d;
      --low-fg: #8fc3ee;
      --low-bg: #17293a;
      --low-border: #2b4b68;
      --shadow: 0 1px 2px rgba(0,0,0,0.3), 0 6px 20px rgba(0,0,0,0.35);
    }
  }

  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: var(--sans);
    font-size: 16px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
