23	pub fn changed_since_last_tag<R: CommandRunner>(
24	    runner: &R,
25	    root: &Path,
26	    pkg: &Package,
27	    tags: &TagIndex,
28	) -> Result<bool, GraphError> {
29	    let Some(last) = tags.last_tag(&pkg.id) else {
30	        return Ok(true);
31	    };
32	
33	    // `GitAccess` transparently tries native gix first and falls back to
34	    // `runner` when unavailable (always true on wasm32); a failure here
35	    // (either backend) is not fatal -- it just means the cheap short-circuit
36	    // below is skipped in favor of the exact `git diff --quiet` check.
37	    let git = GitAccess::discover(root, runner);
38	    if let Ok(commits) = git.commits_since(Some(last.name.as_str()), &[]) {
39	        if !commits.is_empty() {
40	            return Ok(true);
41	        }
42	    }
43	
44	    let paths = package_paths(pkg);
45	    let mut args = vec!["diff", "--quiet", last.name.as_str(), "--"];
46	    let path_strs: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
47	    for p in &path_strs {
48	        args.push(p);
49	    }
50	
51	    let output = runner.run("git", &args, root)?;
52	    Ok(!output.success())
53	}
