18	/// Per-package accumulator: pending changeset names and their max severity.
19	type PendingChangesets = BTreeMap<PackageId, (Vec<String>, Option<Severity>)>;
20	
21	/// Resolves each changeset entry to at most one package and accumulates the
22	/// pending changeset names and max severity per package.
23	///
24	/// Uses [`resolve_target_package`] (the same ambiguity-checking resolution
25	/// `aggregate()` relies on) rather than a bare `matches()` loop, so a
26	/// changeset entry naming a bare package that exists in two or more
27	/// ecosystems (e.g. `cargo/foo` and `npm/foo`) errors instead of silently
28	/// attaching the changeset to every matching package.
29	fn resolve_pending_changesets<'a>(
30	    packages: impl Iterator<Item = &'a Package> + Clone,
31	    loaded_changesets: &[LoadedChangeset],
32	) -> Result<PendingChangesets, GraphError> {
33	    let mut pending: PendingChangesets = BTreeMap::new();
34	    for lc in loaded_changesets {
35	        for entry in &lc.changeset.entries {
36	            let Ok(entry_id) = PackageId::parse(&entry.name) else {
37	                continue;
38	            };
39	            let Some(resolved) = resolve_target_package(packages.clone(), &entry_id)? else {
40	                continue;
41	            };
42	            let name = lc
43	                .path
44	                .file_stem()
45	                .and_then(|s| s.to_str())
46	                .unwrap_or("unknown")
47	                .to_string();
48	            let state = pending.entry(resolved.id.clone()).or_default();
49	            state.0.push(name);
50	            state.1 = match (state.1, entry.severity) {
51	                (None, s) => Some(s),
52	                (Some(cur), s) => Some(cur.max(s)),
53	            };
54	        }
55	    }
56	    Ok(pending)
57	}
