59	pub fn status<R: CommandRunner, D: DependencyResolver>(
60	    ws: &Workspace<'_, R, D>,
61	    opts: &StatusOptions,
62	) -> Result<StatusReport, GraphError> {
63	    let mut packages = Vec::new();
64	    let base_versions = ws.base_versions()?;
65	    let loaded_changesets = crate::load_changesets(&ws.root, &ws.config)?;
66	    let tags = ws.tags()?;
67	
68	    let all_packages: Vec<&Package> = ws.graph.packages().collect();
69	    let pending = resolve_pending_changesets(all_packages.iter().copied(), &loaded_changesets)?;
70	
71	    for pkg in all_packages.iter().copied() {
72	        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
73	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
74	                path: pkg
75	                    .manifests
76	                    .first()
77	                    .map(|m| m.path.clone())
78	                    .unwrap_or_default(),
79	                field: "version",
80	            })
81	        })?;
82	        let last_tag = tags.last_tag(&pkg.id).map(|t| t.name.clone());
83	        let changed = changed_since_last_tag(ws.runner, &ws.root, pkg, tags)?;
84	
85	        let (pkg_changesets, max_sev) = pending.get(&pkg.id).cloned().unwrap_or_default();
86	
87	        packages.push(callisto_model::StatusPackageRecord {
88	            package: pkg.id.clone(),
89	            current_version,
90	            last_tag,
91	            pending_severity: max_sev,
92	            changed_since_last_tag: changed,
93	            pending_changesets: pkg_changesets,
94	        });
95	    }
96	
97	    let mut diagnostics = ws.graph.diagnostics().to_vec();
98	    escalate(&mut diagnostics, opts.strict, opts.strict_graph);
99	
100	    Ok(StatusReport {
101	        schema_version: SCHEMA_VERSION,
102	        packages,
103	        diagnostics,
104	    })
105	}
